window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-976b9a683b67c042"]={"versions": [{"id": "FIG-976b9a683b67c042", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-Aktivitätsdiagramm (Software & Systems Process Engineering Metamodel) im Kontext der AUTOSAR-Methodik (BSW-Designprozess). Es beschreibt den Prozessschritt zur Definition von Schnittstelleneinträgen für Basissoftware-Module (BSW Entries).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität (Task Definition)</strong>:</li>\n<li><code>Define BSW Entries</code> (Kardinalität <code>1</code> bezüglich des Designers bzw. <code>0..1</code> bezüglich des Modulentwicklers)</li>\n<li><strong>Rollen</strong>:</li>\n<li><code>Basic Software Designer</code> (führt die Aktivität regulär aus; Assoziation <code>«performs»</code> mit Kardinalität <code>1</code>)</li>\n<li><code>Basic Software Module Developer</code> (optionaler Ausführender; Assoziation <code>«performs»</code> mit Kardinalität <code>0..1</code>)</li>\n<li><strong>Eingangs-Artefakte</strong>:</li>\n<li><code>BSW Types</code> (Work Product, Kardinalität <code>1</code>, Assoziation <code>«input»</code>)</li>\n<li><code>BSW Standard Package</code> (Package / Composite Work Product, Kardinalität <code>0..1</code>, Assoziation <code>«input»</code>)</li>\n<li><strong>Ausgangs-Artefakt</strong>:</li>\n<li><code>Basic Software Entries</code> (Work Product, Kardinalität <code>1</code>, Assoziation <code>«output»</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität <code>Define BSW Entries</code> wird primär durch die Rolle <code>Basic Software Designer</code> durchgeführt (Multiplizität 1) oder alternativ/ergänzend durch den <code>Basic Software Module Developer</code> (Multiplizität 0..1). Zur Ausführung ist das Artefakt <code>BSW Types</code> zwingend als Eingabe erforderlich (Kardinalität 1). Das <code>BSW Standard Package</code> kann optional als Referenz bzw. Vorgabe herangezogen werden (Kardinalität 0..1). Als Ergebnis der Aktivität wird genau ein Artefakt <code>Basic Software Entries</code> erzeugt (Kardinalität 1).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Definition der <code>Basic Software Entries</code> ist ein normativer Bestandteil der AUTOSAR BSW-Methodik. Sie legt die Funktions- und Schnittstellensignaturen fest, über die BSW-Module mit dem BSW Scheduler bzw. anderen Modulen interagieren. Für Entwickler und Tool-Hersteller bedeutet dies, dass Werkzeuge zur BSW-Modellierung mindestens die Transformation und Verknüpfung von <code>BSW Types</code> in standardisierte BSW-Entry-Deklarationen unterstützen müssen.</p>"}, {"id": "FIG-c1a57df1dac4e18a", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-Aktivitätsdiagramm (Software & Systems Process Engineering Metamodel) im Kontext der AUTOSAR-Methodik (BSW-Designprozess). Es beschreibt den Prozessschritt zur Definition von Schnittstelleneinträgen für Basissoftware-Module (BSW Entries).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität (Task Definition)</strong>:</li>\n<li><code>Define BSW Entries</code> (Kardinalität <code>1</code> bezüglich des Designers bzw. <code>0..1</code> bezüglich des Modulentwicklers)</li>\n<li><strong>Rollen</strong>:</li>\n<li><code>Basic Software Designer</code> (führt die Aktivität regulär aus; Assoziation <code>«performs»</code> mit Kardinalität <code>1</code>)</li>\n<li><code>Basic Software Module Developer</code> (optionaler Ausführender; Assoziation <code>«performs»</code> mit Kardinalität <code>0..1</code>)</li>\n<li><strong>Eingangs-Artefakte</strong>:</li>\n<li><code>BSW Types</code> (Work Product, Kardinalität <code>1</code>, Assoziation <code>«input»</code>)</li>\n<li><code>BSW Standard Package</code> (Package / Composite Work Product, Kardinalität <code>0..1</code>, Assoziation <code>«input»</code>)</li>\n<li><strong>Ausgangs-Artefakt</strong>:</li>\n<li><code>Basic Software Entries</code> (Work Product, Kardinalität <code>1</code>, Assoziation <code>«output»</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität <code>Define BSW Entries</code> wird primär durch die Rolle <code>Basic Software Designer</code> durchgeführt (Multiplizität 1) oder alternativ/ergänzend durch den <code>Basic Software Module Developer</code> (Multiplizität 0..1). Zur Ausführung ist das Artefakt <code>BSW Types</code> zwingend als Eingabe erforderlich (Kardinalität 1). Das <code>BSW Standard Package</code> kann optional als Referenz bzw. Vorgabe herangezogen werden (Kardinalität 0..1). Als Ergebnis der Aktivität wird genau ein Artefakt <code>Basic Software Entries</code> erzeugt (Kardinalität 1).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Definition der <code>Basic Software Entries</code> ist ein normativer Bestandteil der AUTOSAR BSW-Methodik. Sie legt die Funktions- und Schnittstellensignaturen fest, über die BSW-Module mit dem BSW Scheduler bzw. anderen Modulen interagieren. Für Entwickler und Tool-Hersteller bedeutet dies, dass Werkzeuge zur BSW-Modellierung mindestens die Transformation und Verknüpfung von <code>BSW Types</code> in standardisierte BSW-Entry-Deklarationen unterstützen müssen.</p>"}], "trans": [{"from": "FIG-976b9a683b67c042", "to": "FIG-c1a57df1dac4e18a", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
